// 1. Obtener la respuesta de la IA
const aiResponse = $input.item.json.output || $input.item.json.text || $input.item.json.response || "";

// 2. Extraer datos del mensaje y canal
const webhookData = $("Webhook").item.json.body || {};
const conversation = webhookData.conversation || {};
const account = webhookData.account || {};
const channel = conversation.channel || "";

let formattedText = aiResponse;

// 3. Formatear según canal (Meta / WhatsApp vs Telegram)
if (channel.includes("Whatsapp") || channel.includes("Facebook") || channel.includes("Instagram")) {
  formattedText = formattedText.replace(/\*\*(.*?)\*\*/g, '*$1*');
  formattedText = formattedText.replace(/\[(.*?)\]\((.*?)\)/g, '$1: $2');
}

return {
  json: {
    content: formattedText,
    conversation_id: conversation.id,
    account_id: account.id,
    channel: channel
  }
};
